import{_ as o,B as s,o as d,c as l,a8 as c,a,E as i,f as t}from"./chunks/framework.CNIpabDg.js";const v=JSON.parse('{"title":"Firmware update","description":"Experimental signed firmware update transactions, native NOR simulation and the privileged VFS device.","frontmatter":{"layout":"doc","docType":"explanation","description":"Experimental signed firmware update transactions, native NOR simulation and the privileged VFS device."},"headers":[],"relativePath":"explanation/architecture/libraries/firmware_update.md","filePath":"explanation/architecture/libraries/firmware_update.md","lastUpdated":1793045410000}'),p={name:"explanation/architecture/libraries/firmware_update.md"};function h(u,e,m,f,g,k){const n=s("HostReference"),r=s("CodeReference");return d(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793045410000"},[e[6]||(e[6]=c(`<h1 id="firmware-update" tabindex="-1">Firmware update <a class="header-anchor" href="#firmware-update" aria-label="Permalink to &quot;Firmware update&quot;">​</a></h1><p>Core #532 adds the <strong>experimental</strong> <code>xila-firmware-update</code> library and an end-to-end native NOR-flash simulator. This is the prototype portion of <a href="https://github.com/xila-project/core/issues/526" target="_blank" rel="noreferrer">Core #526</a>, <strong>not</strong> an ESP32-S3 OTA implementation or production secure bootloader.</p><h2 id="transaction-model" tabindex="-1">Transaction model <a class="header-anchor" href="#transaction-model" aria-label="Permalink to &quot;Transaction model&quot;">​</a></h2><p>The <code>no_std</code> core defines an allocator-independent <code>Update&lt;B&gt;</code> transaction owner around a platform <code>FirmwareBackend</code>. The backend owns image format, verification trust, staging geometry and boot state. The intended lifecycle is:</p><ol><li>Begin a transaction for an exact declared image length and backend-specific metadata.</li><li>Stream bytes to durable staging, handling short writes and failures explicitly.</li><li>Finish and verify the stored image, receiving a backend-owned proof bound to that staging generation.</li><li>Activate only the verified generation, then attempt a trial boot.</li><li>Confirm the running image or recover the previous confirmed image. Aborting never activates new firmware.</li></ol><p>The native simulator models NOR erase sectors, 1→0 programming, torn writes, two image slots and redundant boot records. After Core #537, it consumes the <strong>pinned shared verification dependency</strong> from <a href="https://github.com/xila-project/package_manager/tree/main/crates/verification" target="_blank" rel="noreferrer">package_manager</a>, reusing SHA-256 and <strong>strict ordinary Ed25519</strong> from <a href="/explanation/architecture/libraries/verification.html">Verification</a> and uses a <strong>simulator-specific signed manifest</strong>, distinct from XPK or ESP/MCUboot formats.</p><h2 id="device-contract" tabindex="-1">Device contract <a class="header-anchor" href="#device-contract" aria-label="Permalink to &quot;Device contract&quot;">​</a></h2><p>The optional VFS façade is mounted at <code>/devices/system/firmware</code>. It uses Xila&#39;s Unix-like character-device operations instead of exposing flash offsets or slots directly. The root-owned mount uses mode <code>0600</code>, allows <strong>one exclusive opening</strong> (including read-only status openings), and rejects duplicated descriptors.</p><p>The fixed-byte ABI v1 uses command family <code>F</code>: capability/status queries and the write-directed <code>BEGIN</code>, <code>FINISH</code>, <code>ACTIVATE</code>, <code>ABORT</code> and <code>CONFIRM</code> controls. A <code>write</code> streams image bytes after <code>BEGIN</code>. Headers carry explicit version/reserved bytes and each operation validates lengths and state. VFS <strong>read-only handles cannot issue write-directed controls</strong>, including through WASI forwarding. Closing a handle never activates firmware.</p><p>Capabilities describe guarantees separately: <strong>authenticated update</strong>, <strong>functional revert</strong>, <strong>verified boot</strong>, and <strong>hardware root</strong>. The simulator implements only the first two; its mutable security floor is <strong>not hardware-enforced anti-rollback</strong>.</p><h2 id="native-simulator-and-validation" tabindex="-1">Native simulator and validation <a class="header-anchor" href="#native-simulator-and-validation" aria-label="Permalink to &quot;Native simulator and validation&quot;">​</a></h2><p>Core includes <code>xila-firmware-sim</code>, a process-restart test harness, persistent raw-file backing and deterministic fault injection. Tests exercise corrupted signatures, stale proofs, failed operations, torn writes and trial/confirm/revert recovery across restarts.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila-firmware-update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> native</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila-firmware-update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> native</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila-firmware-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>See Core&#39;s README for complete simulator arguments, storage layout and signed-test-image recipes. The library&#39;s focused test suite uses 22 native tests; the final integrated Core run for #532 passed 1,101 workspace tests. Those results are <strong>not hardware qualification</strong>.</p><h2 id="hardware-and-security-limits" tabindex="-1">Hardware and security limits <a class="header-anchor" href="#hardware-and-security-limits" aria-label="Permalink to &quot;Hardware and security limits&quot;">​</a></h2><p>ESP32-S3 secure boot uses the platform&#39;s provisioned trust and bootloader verification, not the simulator&#39;s Ed25519 format. Any future adapter must use platform OTA APIs, partitions, recovery state and key policy. MCUboot-based Nordic boards have different trailer, signature and swap constraints. Power-loss, brownout, secure-key provisioning, real flash wear and target-specific RAM/stack/flash costs all remain to be validated.</p><p>No production boot protection, signing-key management, update transport or application-package enforcement is shipped by this prototype. The separate #402, #491 and #495 work items own package manifests, installation trust and executable enforcement.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2>`,18)),a("ul",null,[a("li",null,[i(n,{crate:"firmware_update"}),e[0]||(e[0]=t(" — transaction API Rustdoc.",-1))]),a("li",null,[i(r,{path:"libraries/firmware_update/README.md"}),e[1]||(e[1]=t(" — platform audit and reproducible simulator procedure.",-1))]),a("li",null,[i(r,{path:"libraries/firmware_update/src/lib.rs"}),e[2]||(e[2]=t(" — transaction and capability contracts.",-1))]),a("li",null,[i(r,{path:"libraries/firmware_update/src/device.rs"}),e[3]||(e[3]=t(" — VFS device command ABI.",-1))]),a("li",null,[i(r,{path:"libraries/firmware_update/src/simulator.rs"}),e[4]||(e[4]=t(" — native reference backend.",-1))]),e[5]||(e[5]=a("li",null,[a("a",{href:"/explanation/architecture/subsystems/virtual_file_system.html"},"Virtual file system"),t(" — namespace and access rules.")],-1))])])}const y=o(p,[["render",h]]);export{v as __pageData,y as default};
